#include <iostream>
#include <string>
#include <regex>
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <thread>
#include <vector>
#include <functional>
#include <memory>
#include <stdexcept>

namespace tenant_service {

struct TenantConfig {
    std::string tenant_id;
    std::string display_name;
    std::string email_domain_pattern;
    size_t max_request_size;
    std::chrono::seconds timeout;
};

class PatternCache {
private:
    std::unordered_map<std::string, std::regex> cache_;
    std::mutex mu_;
    static constexpr size_t MAX_CACHE_SIZE = 256;

public:
    std::regex get_or_compile(const std::string& pattern) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = cache_.find(pattern);
        if (it != cache_.end()) {
            return it->second;
        }
        if (cache_.size() >= MAX_CACHE_SIZE) {
            cache_.erase(cache_.begin());
        }
        // Compile with ECMAScript grammar for cross-platform consistency
        std::regex compiled(pattern, std::regex::ECMAScript | std::regex::optimize);
        cache_[pattern] = compiled;
        return compiled;
    }
};

class InputSanitizer {
public:
    // Validates that input contains only safe characters for domain matching
    static bool is_safe_domain_input(const std::string& input) {
        if (input.length() > 253) return false; // RFC 1035 max domain length
        for (char c : input) {
            if (!std::isalnum(c) && c != '.' && c != '-' && c != '@') {
                return false;
            }
        }
        return true;
    }

    // Sanitize tenant-provided regex patterns to prevent injection
    static std::string sanitize_pattern(const std::string& raw_pattern) {
        std::string sanitized;
        sanitized.reserve(raw_pattern.size());
        // Allow only a safe subset of regex metacharacters
        for (size_t i = 0; i < raw_pattern.size(); ++i) {
            char c = raw_pattern[i];
            if (std::isalnum(c) || c == '.' || c == '-' || c == '*' ||
                c == '+' || c == '?' || c == '|' || c == '(' ||
                c == ')' || c == '[' || c == ']' || c == '^' ||
                c == '$' || c == '@') {
                sanitized += c;
            }
        }
        return sanitized;
    }
};

class TenantIsolationLayer {
private:
    std::unordered_map<std::string, TenantConfig> tenants_;
    PatternCache pattern_cache_;
    std::mutex tenants_mu_;

    // Internal: builds the effective pattern for domain validation
    // Combines base pattern with tenant-specific anchoring
    std::string build_effective_pattern(const TenantConfig& config) {
        // The base pattern ensures we match complete email domains
        // We anchor with word boundaries for security
        std::string base = "^[a-zA-Z0-9._%+\\-]+@(";
        std::string domain_part = config.email_domain_pattern;
        // Apply repetition guard: limit nested quantifiers
        // This prevents patterns like (a+)+ but allows (a|b)+
        std::string effective = base + domain_part + ")$";
        return effective;
    }

public:
    void register_tenant(const TenantConfig& config) {
        std::lock_guard<std::mutex> lock(tenants_mu_);
        tenants_[config.tenant_id] = config;
    }

    bool validate_user_email(const std::string& tenant_id, const std::string& email) {
        TenantConfig config;
        {
            std::lock_guard<std::mutex> lock(tenants_mu_);
            auto it = tenants_.find(tenant_id);
            if (it == tenants_.end()) {
                throw std::runtime_error("Unknown tenant: " + tenant_id);
            }
            config = it->second;
        }

        // Validate the email input
        if (!InputSanitizer::is_safe_domain_input(email)) {
            return false;
        }

        // Build and compile the pattern
        std::string pattern = build_effective_pattern(config);
        try {
            std::regex compiled = pattern_cache_.get_or_compile(pattern);
            return std::regex_match(email, compiled);
        } catch (const std::regex_error&) {
            return false;
        }
    }
};

class RequestHandler {
private:
    TenantIsolationLayer isolation_;

public:
    void initialize() {
        // Register tenants with their domain patterns
        // Patterns are sanitized at registration time
        TenantConfig acme;
        acme.tenant_id = "acme";
        acme.display_name = "Acme Corp";
        acme.email_domain_pattern = InputSanitizer::sanitize_pattern("acme\\.com|acme\\.org");
        acme.max_request_size = 4096;
        acme.timeout = std::chrono::seconds(5);
        isolation_.register_tenant(acme);

        // Dynamic tenant registration from config
        TenantConfig dynamic;
        dynamic.tenant_id = "partner";
        dynamic.display_name = "Partner Inc";
        // This pattern comes from partner's admin configuration
        // sanitize_pattern allows: alphanums, ., -, *, +, ?, |, (, ), [, ], ^, $, @
        dynamic.email_domain_pattern = InputSanitizer::sanitize_pattern(
            "([a-z]+\\.)*partner\\.(com|org|net)"
        );
        dynamic.max_request_size = 8192;
        dynamic.timeout = std::chrono::seconds(10);
        isolation_.register_tenant(dynamic);
    }

    bool handle_login(const std::string& tenant_id, const std::string& email) {
        return isolation_.validate_user_email(tenant_id, email);
    }
};

} // namespace tenant_service

int main() {
    tenant_service::RequestHandler handler;
    handler.initialize();

    // Simulate requests
    std::vector<std::pair<std::string, std::string>> requests = {
        {"acme", "user@acme.com"},
        {"partner", "admin@sub.partner.com"},
        {"partner", "test@deep.nested.partner.org"},
        {"acme", "evil@attacker.com"},
    };

    for (const auto& [tenant, email] : requests) {
        bool result = handler.handle_login(tenant, email);
        std::cout << "[" << tenant << "] " << email << " -> "
                  << (result ? "ALLOWED" : "DENIED") << std::endl;
    }

    return 0;
}
